alter table public.pricing_plans add column if not exists consumer_or_business text;
update public.pricing_plans set consumer_or_business=case when code in ('free','premium','family') then 'consumer' else 'business' end where consumer_or_business is null;
update public.pricing_plans set monthly_price_cents=case code when 'free' then 0 when 'premium' then 500 when 'family' then 2000 else monthly_price_cents end;
update public.pricing_plans set description=case code when 'free' then 'Core restroom discovery with basic search and community participation' when 'premium' then 'Full consumer Kleenest experience' when 'family' then 'Premium for the owner plus up to four additional family members' when 'standard' then 'Basic business presence and core metrics' when 'growth' then 'Growth tools, campaigns and earned promotional perks' when 'enterprise' then 'Advanced business intelligence and enterprise capabilities' when 'fleet' then 'Fleet restroom intelligence, routing and operations' else description end;
insert into public.pricing_plans(code,name,monthly_price_cents,description,features,consumer_or_business) values ('family','Family Premium',2000,'Premium for the owner plus up to four additional family members','["up_to_5_people","all_premium_features","favorites","route_by_favorite","no_ads"]','consumer') on conflict(code) do update set monthly_price_cents=excluded.monthly_price_cents,description=excluded.description,features=excluded.features,consumer_or_business=excluded.consumer_or_business,active=true;
create table if not exists public.family_accounts (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references auth.users(id) on delete cascade, plan_code text not null default 'family' references public.pricing_plans(code), max_members integer not null default 5 check(max_members=5), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_family_members_group_user on public.family_members(group_id,user_id);
create or replace function public.family_has_premium_access(p_user_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.family_members fm join public.family_accounts fa on fa.id=fm.group_id where fm.user_id=p_user_id and fa.plan_code='family' and (select count(*) from public.family_members x where x.group_id=fm.group_id)<=5); $$;
create or replace function public.get_effective_consumer_tier(p_user_id uuid) returns text language sql stable security definer set search_path=public as $$ select case when public.family_has_premium_access(p_user_id) then 'premium' else coalesce((select subscription_tier::text from public.profiles where id=p_user_id),'free') end; $$;
create or replace function public.get_favorite_locations(p_user_id uuid) returns table(location_id uuid, favorited_at timestamptz) language sql stable security invoker as $$ select f.location_id,f.created_at from public.favorites f where f.user_id=p_user_id order by f.created_at desc; $$;
create or replace function public.record_favorite_route_event(p_location_id uuid,p_user_id uuid,p_from_lat numeric default null,p_from_lng numeric default null) returns uuid language plpgsql security invoker as $$ declare v_id uuid; begin insert into public.location_route_events(location_id,user_id,source,from_lat,from_lng) values(p_location_id,p_user_id,'favorite',p_from_lat,p_from_lng) returning id into v_id; return v_id; end; $$;
create or replace function public.location_engagement_metrics(p_location_id uuid) returns table(favorite_count bigint,favorite_route_count bigint) language sql stable security invoker as $$ select (select count(*) from public.favorites where location_id=p_location_id),(select count(*) from public.location_route_events where location_id=p_location_id and source='favorite'); $$;
create index if not exists idx_favorites_location on public.favorites(location_id);
create index if not exists idx_location_route_events_location_source on public.location_route_events(location_id,source);
